(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["pharmacology-i-exam-1-pharm-exam-1-master-exam-form-f"]={"title":"Pharmacology I Exam 1 Master Exam — Form F","category":"Pharmacology I","exam":"Exam 1","sem":"fall-2026","questions":[{"q":"Which drugs besides corticosteroids induce acne?","choices":["Antiepileptics, tuberculostatics and lithium","Beta blockers and calcium channel blockers","Antihistamines and decongestants","Statins and fibrates"],"answer":0,"exp":"Correct, alongside systemic corticosteroids. — 02. Dermatology Medications(1).pptx, Slide 15"},{"q":"Why does stopping a steroid initially worsen drug-induced acne?","choices":["Inflammation increases as the steroid stops","Bacterial counts rebound immediately","Sebum production doubles on withdrawal","Keratinisation accelerates sharply"],"answer":0,"exp":"Correct, so the eruption looks worse before it settles. — 02. Dermatology Medications(1).pptx, Slide 15"},{"q":"What distinguishes the bacterial ribosome from the mammalian one?","choices":["Bacterial is 80S, mammalian is 70S","Both are 70S but differ in composition","Bacterial is 70S, mammalian is 80S","Bacterial ribosomes lack a large subunit"],"answer":2,"exp":"Correct, which is why high drug levels can affect human ribosomes. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 53"},{"q":"Why is timolol used in chronic open-angle glaucoma?","choices":["It increases outflow through the trabecular meshwork","It constricts the pupil to open the angle","It reduces production of aqueous humour","It dilates the ciliary body vessels"],"answer":2,"exp":"Correct, and it is more potent than propranolol. — 03. ANS Pharmacology(1).pptx, Slide 119"},{"q":"Which non-drug measure reduces night-time itching in a child with eczema?","choices":["A sedating antihistamine","A hot bath before bed","Withholding lubricant after bathing","Letting the fingernails grow long"],"answer":0,"exp":"Correct, alongside short fingernails and lukewarm baths. — 02. Dermatology Medications(1).pptx, Slide 36"},{"q":"Which tetracycline causes the most tooth discoloration?","choices":["Minocycline","Tetracycline","Tigecycline","Doxycycline"],"answer":3,"exp":"Correct, more so than the other tetracyclines. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 63"},{"q":"Why are fever and chills pre-treated during amphotericin B infusion?","choices":["They are driven by interleukin-1 and tumour necrosis factor","They represent an immunoglobulin E allergy","They signal an infusion running too slowly","They indicate the electrolyte disturbance beginning early"],"answer":0,"exp":"Correct, so paracetamol, antihistamines and steroids are given first. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 98"},{"q":"Which vehicle suits the scalp and other hairy areas?","choices":["Ointment","Paste","Cream","Gel or foam"],"answer":3,"exp":"Correct, because it foams well and leaves low residue. — 02. Dermatology Medications(1).pptx, Slide 8"},{"q":"Which agent is used for chronic management of myasthenia gravis?","choices":["Pyridostigmine","Edrophonium","Physostigmine","Donepezil"],"answer":0,"exp":"Correct, while edrophonium is the diagnostic agent. — 03. ANS Pharmacology(1).pptx, Slide 39"},{"q":"Which adverse effects follow bethanechol?","choices":["Sweating, salivation, flushing and low blood pressure","Dry mouth, blurred vision and urinary retention","Tachycardia, hypertension and fasciculations","Tremor, restlessness and anxiety"],"answer":0,"exp":"Correct, alongside nausea, abdominal pain and bronchospasm. — 03. ANS Pharmacology(1).pptx, Slide 31"},{"q":"What does sulfamethoxazole block?","choices":["Dihydrofolic acid becoming tetrahydrofolic acid","Folic acid absorption from the gut","Para-aminobenzoic acid becoming dihydrofolic acid","Conversion of tetrahydrofolate to thymidine"],"answer":2,"exp":"Correct, one step upstream of trimethoprim. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 82"},{"q":"Which first generation cephalosporin is taken by mouth for cellulitis?","choices":["Cefazolin","Cefuroxime","Cefprozil","Cephalexin"],"answer":3,"exp":"Correct, at 500 milligrams every 6 to 12 hours. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 32"},{"q":"Why is albuterol preferred for chronic asthma over epinephrine?","choices":["Longer duration and less cardiac stimulation","It is the only agent that reaches the airway","It can be given by mouth effectively","It has no adverse effects at all"],"answer":0,"exp":"Correct, as a selective beta-2 agonist. — 03. ANS Pharmacology(1).pptx, Slide 84"},{"q":"Which azole works against the Zygomycetes?","choices":["Voriconazole","Fluconazole","Itraconazole","Posaconazole"],"answer":3,"exp":"Correct, and it is the only azole that does. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 105"},{"q":"Why is a single dose of fluconazole enough for vaginal candidiasis?","choices":["It is excreted in the urine","It binds irreversibly to fungal enzymes","It is stored in keratin precursor cells","It has an extremely long plasma half-life"],"answer":0,"exp":"Correct, and it also has the best oral absorption of the azoles. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 106"},{"q":"How does atropine affect heart rate?","choices":["Tachycardia at every dose, regardless of amount","Bradycardia at low doses, tachycardia at higher doses","Bradycardia at all doses","No effect on heart rate at all"],"answer":1,"exp":"Correct, and it is given in cardiac arrest for bradycardia. — 03. ANS Pharmacology(1).pptx, Slide 49"},{"q":"How does daptomycin kill bacteria?","choices":["By causing bacterial depolarisation","By binding the 50S ribosomal subunit","By blocking cell wall cross-linking","By inhibiting DNA gyrase"],"answer":0,"exp":"Correct, halting DNA, RNA and protein synthesis at once. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 72"},{"q":"What is the once-daily amikacin dose?","choices":["7 milligrams per kilogram","15 milligrams per kilogram","25 to 30 milligrams per kilogram","4 to 6 milligrams per kilogram"],"answer":1,"exp":"Correct, against 7 milligrams per kilogram for the other two. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 69"},{"q":"What does acetylcholine do to heart rate and blood pressure?","choices":["Lowers both","Raises both","Lowers rate but raises pressure","Leaves both unchanged"],"answer":0,"exp":"Correct, decreasing cardiac output as well. — 03. ANS Pharmacology(1).pptx, Slide 27"},{"q":"What does adding a beta-lactamase inhibitor to an aminopenicillin achieve?","choices":["Antipseudomonal activity and Gram-negative reach","Coverage of resistant Staphylococcus aureus","Anaerobic cover including Bacteroides, plus MSSA","Central nervous system penetration for meningitis"],"answer":2,"exp":"Correct, which is why it suits bites and diabetic foot infection. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 25"},{"q":"Which four factors drive acne?","choices":["Sebum, sweating, sunlight and diet alone","Sebum, keratinisation, bacteria and inflammation","Hormones, genetics, race and environmental heat","Infection, allergy, trauma and stress"],"answer":1,"exp":"Correct, making it a multifactorial disease. — 02. Dermatology Medications(1).pptx, Slide 10"},{"q":"What is amphetamine used to treat?","choices":["Hypertension and stable angina pectoris","Hyperactivity, narcolepsy, appetite control","Shock requiring vascular resistance","Motion sickness on a long journey"],"answer":1,"exp":"Correct, alongside its central stimulant activity. — 03. ANS Pharmacology(1).pptx, Slide 100"},{"q":"How does cocaine act as a local anaesthetic?","choices":["It blocks alpha-1 receptors locally","It blocks neuronal sodium channels","It depletes local catecholamine stores","It inhibits monoamine oxidase locally"],"answer":1,"exp":"Correct, separate from its blockade of norepinephrine reuptake. — 03. ANS Pharmacology(1).pptx, Slide 102"},{"q":"How is ertapenem dosed?","choices":["500 milligrams intravenously every 6 hours","1 to 2 grams intravenously every 8 hours","500 milligrams intravenously every 8 hours","1 gram intravenously once daily"],"answer":3,"exp":"Correct, infused over 30 minutes. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 44"},{"q":"Carbapenems are the drug of choice for which infections?","choices":["Methicillin-resistant Staphylococcus aureus bacteraemia","Uncomplicated urinary infection in the community","Syphilis and other spirochaetal infections","Multidrug-resistant Gram-negative and ESBL producers"],"answer":3,"exp":"Correct, along with nosocomial infection and meningitis. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 43"},{"q":"Which corticosteroid class is the least potent?","choices":["Class 6, the mild group","Class 5, lower mid-strength","Class 7, which is hydrocortisone","Class 1, the superpotent group"],"answer":2,"exp":"Correct, at strengths from 0.5 to 2.5 percent. — 02. Dermatology Medications(1).pptx, Slide 42"},{"q":"Which herpes simplex type is associated with the genitals and rectum?","choices":["Type 2","Type 1","Varicella-zoster","Cytomegalovirus"],"answer":0,"exp":"Correct, while type 1 involves mouth, face, skin and brain. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 119"},{"q":"Where are alpha-2 receptors located?","choices":["On the postsynaptic membrane of the effector organ","On presynaptic nerve endings and other cells","Only within the central nervous system","On the neuromuscular endplate"],"answer":1,"exp":"Correct, whereas alpha-1 sits postsynaptically on the effector organ. — 03. ANS Pharmacology(1).pptx, Slide 76"},{"q":"What happened to ephedra-containing herbal products in 2004?","choices":["They were moved behind the pharmacy counter","They were reclassified as prescription only","They were banned by the regulator","They were approved for nasal congestion"],"answer":2,"exp":"Correct, though ephedrine itself was once used to prevent asthma. — 03. ANS Pharmacology(1).pptx, Slide 104"},{"q":"What is tigecycline approved to treat?","choices":["Community-acquired pneumonia and sinusitis","Urinary tract infection and prostatitis","Meningitis and other central nervous system infection","Complicated skin and intra-abdominal infection"],"answer":3,"exp":"Correct, and it covers Enterococcus faecalis but not the resistant form. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 65"},{"q":"What are the three classes of cholinergic antagonist?","choices":["Direct, indirect and mixed acting agents","Reversible and irreversible cholinesterase inhibitors","Antimuscarinics, ganglionic blockers, neuromuscular blockers","Alpha, beta and mixed blockers"],"answer":2,"exp":"Correct, differing by the receptor and site they act on. — 03. ANS Pharmacology(1).pptx, Slide 44"},{"q":"Which sympathetic fibres do the antimuscarinics also block?","choices":["All sympathetic fibres to blood vessels","Cholinergic fibres to salivary and sweat glands","Fibres to the adrenal medulla","None; they act only on parasympathetic nerves"],"answer":1,"exp":"Correct, leaving other sympathetic stimulation unopposed. — 03. ANS Pharmacology(1).pptx, Slide 46"},{"q":"Where are nicotinic receptors located?","choices":["Cardiac cells and bladder smooth muscle only","Central nervous system, adrenal medulla, ganglia, neuromuscular junction","Exocrine glands, gastric parietal cells and bladder muscle only","Vascular smooth muscle exclusively"],"answer":1,"exp":"Correct, spanning both autonomic and somatic sites. — 03. ANS Pharmacology(1).pptx, Slide 24"},{"q":"Which vehicle is the most drying?","choices":["Ointments","Creams","Pastes","Tinctures"],"answer":3,"exp":"Correct, with ointments at the least drying end of the range. — 02. Dermatology Medications(1).pptx, Slide 7"},{"q":"How is a nondepolarising blockade reversed?","choices":["With dantrolene given by intravenous infusion","With neostigmine, pyridostigmine or edrophonium","With pralidoxime","With atropine alone"],"answer":1,"exp":"Correct, by raising acetylcholine in the synaptic gap. — 03. ANS Pharmacology(1).pptx, Slide 64"},{"q":"Which metronidazole side effect requires alcohol counselling?","choices":["Serotonin syndrome with tyramine foods","A disulfiram-like reaction","Chelation reducing drug absorption","Photosensitivity and severe sunburn"],"answer":1,"exp":"Correct, alongside headache, nausea and vomiting. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 86"},{"q":"What is true of the beta-lactamase inhibitors themselves?","choices":["They are bactericidal against Gram-negatives","They reversibly slow the enzyme","They work by blocking penicillin-binding proteins","They have no antibacterial activity of their own"],"answer":3,"exp":"Correct. They irreversibly inactivate beta-lactamase. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 24"},{"q":"Which carbapenem is specifically linked to seizures?","choices":["Imipenem","Ertapenem","Meropenem","Doripenem"],"answer":0,"exp":"Correct, and seizures are named among the things to monitor. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 44"},{"q":"Why is the enteric division called the brain of the gut?","choices":["It contains more neurons than the spinal cord","It uses neurotransmitters found nowhere else","It has no connection to the other divisions","It works independently of the central nervous system"],"answer":3,"exp":"Correct, though both other divisions still modulate it. — 03. ANS Pharmacology(1).pptx, Slide 12"},{"q":"How does the nicotinic receptor work?","choices":["As a G protein coupled receptor","As an enzyme-linked receptor","A ligand-gated channel passing sodium","As a nuclear transcription factor"],"answer":2,"exp":"Correct, opening once two acetylcholine molecules bind. — 03. ANS Pharmacology(1).pptx, Slide 24"},{"q":"Which cephalosporin covers methicillin-resistant Staphylococcus aureus?","choices":["Ceftolozane with tazobactam","Ceftaroline","Cefepime","Ceftazidime"],"answer":1,"exp":"Correct, approved for community-acquired pneumonia and skin infection. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 37"},{"q":"Which muscles are paralysed first by a nondepolarising blocker?","choices":["The diaphragm and intercostal muscles","The muscles of the trunk and neck","Small fast muscles of the face and eye","The limb and finger muscles"],"answer":2,"exp":"Correct, with the diaphragm last and recovery in reverse. — 03. ANS Pharmacology(1).pptx, Slide 65"},{"q":"What is the physical basis of a cream?","choices":["A water in oil emulsion","A water-soluble emulsion of polyethylene glycols","A solution of dissolved drug base","An oil in water emulsion"],"answer":3,"exp":"Correct, whereas an ointment is water in oil. — 02. Dermatology Medications(1).pptx, Slide 8"},{"q":"How do inhalation anaesthetics interact with epinephrine?","choices":["They sensitise the heart, causing tachycardia","They block its cardiac effects entirely","They speed its hepatic metabolism","They convert it to norepinephrine"],"answer":0,"exp":"Correct, which matters during anaesthesia. — 03. ANS Pharmacology(1).pptx, Slide 88"},{"q":"What has carvedilol been shown to do in heart failure?","choices":["Restore ejection fraction to normal","Prevent cardiovascular mortality","Reverse ventricular remodelling completely","Eliminate the need for other therapy"],"answer":1,"exp":"Correct, and it reduces lipid peroxidation and wall thickening. — 03. ANS Pharmacology(1).pptx, Slide 122"},{"q":"Why are topical azoles sometimes combined with a corticosteroid?","choices":["For more rapid symptom relief","To broaden the antifungal spectrum","To prevent resistance developing","To reduce systemic absorption"],"answer":0,"exp":"Correct, though the antifungal course still runs two to three weeks. — 02. Dermatology Medications(1).pptx, Slide 51"},{"q":"Which macrolides are used for Mycobacterium avium complex?","choices":["Erythromycin and azithromycin","Erythromycin and clarithromycin","Clarithromycin and azithromycin","Azithromycin combined with doxycycline"],"answer":2,"exp":"Correct, with ethambutol and possibly rifabutin in disseminated disease. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 56"},{"q":"What happens at higher nicotine doses?","choices":["Blood pressure rises further still","Blood pressure falls as ganglia block","Peristalsis and secretions increase","Heart rate slows progressively"],"answer":1,"exp":"Correct, and gut and bladder activity ceases. — 03. ANS Pharmacology(1).pptx, Slide 59"},{"q":"What do the second generation cephalosporins add over the first?","choices":["Haemophilus influenzae, Neisseria and Enterobacter","Pseudomonas aeruginosa and Acinetobacter","Methicillin-resistant Staphylococcus aureus","Listeria monocytogenes and Enterococcus"],"answer":0,"exp":"Correct, though Enterobacter develops resistance rapidly. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 33"},{"q":"Aminoglycosides are the drug of choice in which settings?","choices":["Community-acquired pneumonia and bronchitis","Febrile neutropenia, sepsis, enterococcal synergy","Clostridium difficile colitis and diarrhoea","Skin and soft tissue infection in the community"],"answer":1,"exp":"Correct, with enterococcal use restricted to synergy dosing. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 68"},{"q":"Which macrolide gastrointestinal effect is worst in children and young adults?","choices":["Constipation and abdominal distension","Pseudomembranous colitis from overgrowth","Nausea, diarrhoea and abdominal pain","Disulfiram-like reaction with alcohol"],"answer":2,"exp":"Correct, because the drug stimulates gut motility. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 57"},{"q":"Which allylamine is available orally?","choices":["Naftifine","Terbinafine","Tolnaftate","Ciclopirox"],"answer":1,"exp":"Correct, while naftifine is topical only. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 112"},{"q":"How does spironolactone help acne?","choices":["As a keratinolytic agent","As a topical antibiotic","As an antiandrogen","By reducing inflammation directly"],"answer":2,"exp":"Correct, and a gel formulation is available alongside oral use. — 02. Dermatology Medications(1).pptx, Slide 29"},{"q":"Which of these is a stated approach to antiviral therapy?","choices":["Neutralising circulating bacterial toxin","Blocking fungal ergosterol synthesis","Blocking viral attachment to cells","Chelating metal ions the virus needs"],"answer":2,"exp":"Correct, one of several points in the viral life cycle. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 118"},{"q":"Which haematological effect limits ganciclovir?","choices":["Haemolytic anaemia in most patients","Polycythaemia requiring venesection","Disseminated intravascular coagulation","Neutropenia in 15 to 40 percent"],"answer":3,"exp":"Correct, with thrombocytopenia also common. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 125"},{"q":"How does reserpine deplete neurotransmitters?","choices":["It blocks release of stored norepinephrine","It inhibits monoamine oxidase","It blocks the postsynaptic receptor","It blocks transport into storage vesicles"],"answer":3,"exp":"Correct, affecting norepinephrine, dopamine and serotonin. — 03. ANS Pharmacology(1).pptx, Slide 123"},{"q":"How long does pilocarpine act?","choices":["Under thirty minutes","About twenty-four hours","Four to eight hours","Two to three days"],"answer":2,"exp":"Correct, with onset within minutes. — 03. ANS Pharmacology(1).pptx, Slide 33"},{"q":"When is an aminoglycoside peak drawn?","choices":["15 to 30 minutes before the next dose","Immediately as the infusion begins","30 minutes after the infusion ends","Four hours after the dose is given"],"answer":2,"exp":"Correct, with troughs 15 to 30 minutes before the next dose. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 69"},{"q":"How do the macrolides inhibit protein synthesis?","choices":["They bind 50S and block transpeptidation","They bind 30S and block transfer RNA docking","They misread the genetic code at the 30S subunit","They prevent formation of the initiation complex at 50S"],"answer":0,"exp":"Correct. Tetracyclines act at the 30S subunit instead. — Antibiotics, Antivirals, and Antifungals.pptx, Slide 54"},{"q":"Which lesions are the non-inflammatory form of acne?","choices":["Papules and pustules","Nodules and cysts","Open and closed comedones","Vesicles and bullae"],"answer":2,"exp":"Correct, as against papulopustular and nodular lesions. — 02. Dermatology Medications(1).pptx, Slide 12"}]};
